"""Clip the internal Bundle body to common physical planes behind its caps.

Only selected first/last derived boundary samples change; the authored source
geometry is untouched. Every interior physical knot and its source rank remain
exact. End ranks are interpolated on the same certified source segments as the
cut positions. The consumer supplies the complete cap surfaces separately.
With independent ends enabled, an uncut end retains its exact source points
and ranks; the original physical-plane and monotonicity checks still apply.
"""
import bpy
from .path_surface_nodes import _Nodes
from . import bundle_axis_nodes as axis, bundle_cap_input_nodes as caps

NAME = 'Prochitecture Streets / Physical Bundle body behind free caps v1'


def build(*, independent_ends=False):
    name = NAME+' / independent ends v1' if independent_ends else NAME
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    tree = bpy.data.node_groups.new(name, 'GeometryNodeTree'); g = _Nodes(tree)
    for side in ('INPUT', 'OUTPUT'):
        for k in range(4):
            tree.interface.new_socket(name='Boundary '+str(k), in_out=side, socket_type='NodeSocketGeometry')
    tree.interface.new_socket(name='Axis', in_out='INPUT', socket_type='NodeSocketVector').default_value = (1., 0., 0.)
    tree.interface.new_socket(name='Maximum Depth', in_out='INPUT', socket_type='NodeSocketFloat').default_value = .5
    if independent_ends:
        for side in ('Start', 'End'):
            tree.interface.new_socket(name='Cut '+side, in_out='INPUT', socket_type='NodeSocketBool').default_value = True
    for name, kind in (('Origin', 'Vector'), ('Axis', 'Vector'), ('Length', 'Float'), ('Valid', 'Bool')):
        tree.interface.new_socket(name=name, in_out='OUTPUT', socket_type='NodeSocket'+kind)
    inp = g.node('NodeGroupInput', 'Certified physical boundary records')
    out = g.node('NodeGroupOutput', 'Common-fibre body records with preserved interior knots')
    index = g.node('GeometryNodeInputIndex', 'Original boundary record index').outputs[0]
    physical = g.named('st_axis_xy', 'FLOAT_VECTOR')
    enabled = [inp.outputs['Cut '+side] for side in ('Start', 'End')] if independent_ends else [True, True]
    rank_node = g.node('GeometryNodeInputNamedAttribute', 'Original source rank')
    rank_node.data_type = 'FLOAT'; rank_node.inputs['Name'].default_value = 'st_station_t'
    rank = rank_node.outputs['Attribute']
    direction = g.vector('NORMALIZE', g.xyz(g.component(inp.outputs['Axis'], 'X'), g.component(inp.outputs['Axis'], 'Y')))
    calls = []
    cuts = []
    origins = []
    for side, at_end in enumerate((False, True)):
        call = g.node('GeometryNodeGroup', 'End physical cut' if at_end else 'Start physical cut')
        call.node_tree = caps.build(); call.inputs['At End'].default_value = at_end
        g.set(direction, call.inputs['Axis'])
        g.set(inp.outputs['Maximum Depth'], call.inputs['Maximum Depth'])
        for k in range(4): g.set(inp.outputs['Boundary '+str(k)], call.inputs['Boundary '+str(k)])
        def world(p):
            return g.vector('ADD', call.outputs['Origin'], g.vector('ADD',
                g.vector('SCALE', call.outputs['Frame X'], g.component(p, 'X')),
                g.vector('SCALE', call.outputs['Frame Y'], g.component(p, 'Y'))))
        points = [world(call.outputs[key]) for key in ('Cut A', 'Inner Cut A', 'Inner Cut B', 'Cut B')]
        plane_origin = world(g.xyz(call.outputs['Cut']))
        if independent_ends:
            endpoints = [g.sample(inp.outputs['Boundary '+str(k)], physical,
                g.math('SUBTRACT', axis._size(g, inp.outputs['Boundary '+str(k)]), 1.) if at_end else 0,
                'FLOAT_VECTOR') for k in range(4)]
            points = [g.switch(enabled[side], endpoint, point, 'VECTOR') for endpoint, point in zip(endpoints, points)]
            original_origin = g.vector('SCALE', g.vector('ADD', endpoints[0], endpoints[3]), .5)
            plane_origin = g.switch(enabled[side], original_origin, plane_origin, 'VECTOR')
        cuts.append(points)
        origins.append(plane_origin)
        calls.append(call)
    origin = origins[0]
    length = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', origins[1], origin), direction)
    checks = [g.compare(length, 2.*axis.AXIS_TOLERANCE, 'GREATER_THAN')]
    checks.extend(g.either(g.boolean('NOT', enabled[side]), call.outputs['Cut Valid'])
                  if independent_ends else call.outputs['Cut Valid'] for side, call in enumerate(calls))
    results = []
    for k in range(4):
        source = inp.outputs['Boundary '+str(k)]; count = axis._size(g, source)
        checks.append(g.sample(source, rank_node.outputs['Exists'], 0, 'BOOLEAN'))
        end_ranks = []
        for side, (a, b) in enumerate(((0, 1), (g.math('SUBTRACT', count, 1.), g.math('SUBTRACT', count, 2.)))):
            p = g.sample(source, physical, a, 'FLOAT_VECTOR'); q = g.sample(source, physical, b, 'FLOAT_VECTOR')
            pa = g.sample(source, rank, a, 'FLOAT'); pb = g.sample(source, rank, b, 'FLOAT')
            delta = g.vector('SUBTRACT', q, p)
            t = g.math('DIVIDE', g.vector('DOT_PRODUCT', g.vector('SUBTRACT', cuts[side][k], p), direction),
                       g.vector('DOT_PRODUCT', delta, direction))
            rank_at_cut = g.math('ADD', pa, g.math('MULTIPLY', t, g.math('SUBTRACT', pb, pa)))
            end_ranks.append(g.switch(enabled[side], pa, rank_at_cut) if independent_ends else rank_at_cut)
            inside = g.all(g.compare(t, 0., 'GREATER_THAN'), g.compare(t, 1., 'LESS_THAN'))
            checks.append(g.either(g.boolean('NOT', enabled[side]), inside) if independent_ends else inside)
        first = g.compare(index, 0, kind='INT'); last = g.compare(index, g.math('SUBTRACT', count, 1.), kind='INT')
        xyz = g.switch(first, physical, cuts[0][k], 'VECTOR')
        xyz = g.switch(last, xyz, cuts[1][k], 'VECTOR')
        t = g.switch(first, rank, end_ranks[0]); t = g.switch(last, t, end_ranks[1])
        recorded = g.store(source, 'st_axis_xy', xyz, 'FLOAT_VECTOR')
        recorded = g.store(recorded, 'st_station_t', t)
        # Semantic endpoint metrics are exactly common after verifying the
        # physical plane residual. Interior coordinates are never stretched.
        metric = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', physical, origin), direction)
        residual = g.switch(first, 0., g.math('ABSOLUTE', metric))
        residual = g.switch(last, residual, g.math('ABSOLUTE', g.math('SUBTRACT', metric, length)))
        checks.append(g.compare(g.stat(recorded, residual, output='Max'), 2e-5, 'LESS_EQUAL'))
        metric = g.switch(first, metric, 0.); metric = g.switch(last, metric, length)
        recorded = g.store(recorded, 'st_bundle_metric', metric)
        value = g.named('st_bundle_metric', 'FLOAT')
        previous = g.sample(recorded, value, g.math('MAXIMUM', 0., g.math('SUBTRACT', index, 1.)), 'FLOAT')
        checks.append(g.stat(recorded, g.either(first, g.compare(g.math('SUBTRACT', value, previous), axis.AXIS_TOLERANCE, 'GREATER_THAN'))))
        # Mesh Line connectivity is inherited unchanged, including the source
        # sample count; the metric-space position is only a lookup coordinate.
        positioned = g.node('GeometryNodeSetPosition', 'Clipped common physical metric')
        g.set(recorded, positioned.inputs['Geometry']); g.set(g.xyz(value), positioned.inputs['Position'])
        results.append(positioned.outputs['Geometry'])
    valid = g.all(*checks)
    for k, result in enumerate(results):
        g.set(g.switch(valid, None, result, 'GEOMETRY'), out.inputs['Boundary '+str(k)])
    for key, value in (('Origin', origin), ('Axis', direction), ('Length', length), ('Valid', valid)):
        g.set(value, out.inputs[key])
    return tree
